{
  "schemaVersion": 1,
  "kind": "editing-regression-plan",
  "status": "planned",
  "catalogs": [
    {
      "path": "tests/editor-interaction-cases.md",
      "expectedCases": 87
    },
    {
      "path": "tests/mobile-web-cases.md",
      "expectedCases": 59
    },
    {
      "path": "tests/mobile-extension-cases.md",
      "expectedCases": 32
    },
    {
      "path": "tests/editor-regression-cases.md",
      "expectedCases": 17
    }
  ],
  "recipes": [
    "tests/editing-suite/recipes/seq-01.json",
    "tests/editing-suite/recipes/seq-02.json",
    "tests/editing-suite/recipes/seq-03.json",
    "tests/editing-suite/recipes/seq-04.json",
    "tests/editing-suite/recipes/seq-05.json",
    "tests/editing-suite/recipes/seq-06.json",
    "tests/editing-suite/recipes/seq-07.json",
    "tests/editing-suite/recipes/seq-08.json",
    "tests/editing-suite/recipes/seq-09.json",
    "tests/editing-suite/recipes/seq-10.json",
    "tests/editing-suite/recipes/seq-11.json",
    "tests/editing-suite/recipes/seq-12.json"
  ],
  "guards": [
    {
      "id": "G01",
      "title": "Intent correlation",
      "owner": "RGS-1.4",
      "negativeControl": "Duplicate notification then identical legitimate insertion must yield exactly two intents."
    },
    {
      "id": "G02",
      "title": "Atomic compound edits",
      "owner": "RGS-1.2",
      "negativeControl": "Final prepare failure must expose zero mutations, updates and history changes."
    },
    {
      "id": "G03",
      "title": "Resulting selection",
      "owner": "RGS-1.2",
      "negativeControl": "Corrupt direction, affinity or widget insertion selection kind; the checkpoint fails."
    },
    {
      "id": "G04",
      "title": "Pending mark lifetime",
      "owner": "RGS-1.2",
      "negativeControl": "Swap null and explicit empty marks or leak an override across selection movement."
    },
    {
      "id": "G05",
      "title": "Composition ownership",
      "owner": "RGS-1.4",
      "negativeControl": "Commit Enter must not split; the next deliberate Enter must split."
    },
    {
      "id": "G06",
      "title": "UTF-16 and grapheme boundaries",
      "owner": "RGS-1.2",
      "negativeControl": "Move range inside a surrogate or delete half a grapheme; exact vector comparison fails."
    },
    {
      "id": "G07",
      "title": "Origin and undo boundaries",
      "owner": "RGS-1.3",
      "negativeControl": "Merge one-character paste into typing or undo a remote edit; history checkpoints fail."
    },
    {
      "id": "G08",
      "title": "Notification isolation",
      "owner": "RGS-1.6",
      "negativeControl": "Throw or request a command during notification; no rollback, duplicate update or reentrant write."
    },
    {
      "id": "G09",
      "title": "Renderer echo ownership",
      "owner": "RGS-1.4",
      "negativeControl": "Renderer echo and genuine input in one turn must retain only the genuine new intent."
    },
    {
      "id": "G10",
      "title": "Normalization termination",
      "owner": "RGS-1.5",
      "negativeControl": "Oscillating repair rules exceed a bounded fixed-point check and fail with a minimal trace."
    },
    {
      "id": "G11",
      "title": "Async target and lifetime",
      "owner": "RGS-1.6",
      "negativeControl": "Late completion after target/session disposal cannot edit or refocus another target."
    },
    {
      "id": "G12",
      "title": "Nested event ownership",
      "owner": "RGS-1.7",
      "negativeControl": "An inner input consumes clipboard events while the outer document remains unchanged."
    },
    {
      "id": "G13",
      "title": "Stable identity across view changes",
      "owner": "RGS-1.7",
      "negativeControl": "Change presenter tag then type sentinel; original identity and mapping survive."
    },
    {
      "id": "G14",
      "title": "Independent evidence",
      "owner": "RGS-1.8",
      "negativeControl": "Alter expected snapshot/count/source revision or remove a required case; qualification fails."
    }
  ]
}
